import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/M-HIS1.Cb88xi6q.js";import{_ as r,o as a,c as o,a3 as i}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Menu principal","description":"","frontmatter":{"source_hash":"212cef4b4a","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/use/hamburger.md","filePath":"fr/use/hamburger.md"}'),n={name:"fr/use/hamburger.md"};function l(u,e,p,c,m,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p></div><p>De nombreux éléments peuvent être ajoutés à ce menu ; par défaut, vous y trouverez les suivants :</p><p><strong>Écran d&#39;accueil</strong> revient simplement à l&#39;écran principal.</p><p><a href="./../troubleshoot/systemstatus.html"><strong>État du système</strong></a> affiche des informations internes sur votre source de données, le partage et l&#39;état de la montre.</p><p><a href="./alarms.html#snooze-alert"><strong>Mise en veille Alertes</strong></a> vous propose des options pour mettre en veille ou désactiver les alertes.</p><p><a href="./statistics.html"><strong>Statistiques</strong></a> fournit des statistiques de base.</p><p><a href="#history"><strong>Historique</strong></a> vous permet de parcourir les données des jours précédents.</p><p><a href="./settings.html"><strong>Paramètres</strong></a> ouvre le menu des paramètres.</p><p>Le menu peut aussi afficher d&#39;autres entrées si vous ajoutez des éléments ou lorsque vous utilisez un capteur :<br> vous verrez les actions sur le capteur si xDrip est directement connecté à un capteur, ainsi que sur un abonné xDrip Sync si le téléphone principal l&#39;est.</p><p><strong><a href="./startsensor.html">Démarrer le capteur</a></strong> ou <strong><a href="./stopsensor.html">Arrêter le capteur</a></strong> : avant d&#39;utiliser ces fonctions, consultez la section correspondant à votre <a href="./../install/datasource.html#sensor-selection">capteur</a>.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Un abonné xDrip Sync peut transmettre à distance le démarrage ou l&#39;arrêt du capteur (si le capteur le permet) et les étalonnages.<br> Soyez extrêmement prudent si vous utilisez ces fonctions sur un abonné alors que le xDrip principal accepte les actions des abonnés.</p></div><p>Pour les transmetteurs Bluetooth (<a href="./../install/libreBT.html">Libre</a>), vous verrez aussi <strong>Scan Bluetooth</strong>.</p><p><strong>Alertes de niveau</strong> s&#39;affiche si cette option est activée dans <a href="./alarms.html#glucose-level-alerts-list">Alarmes et alertes</a>.</p><p><strong>Tableau de données de glycémie</strong>, <strong>Graphe de calibration</strong> et <strong>Tableau de calibrations</strong> doivent être <a href="./lesscommon.html">ajoutés</a> manuellement si vous utilisez l&#39;<a href="./../calibrate/calibrate.html#native-and-xdrip-algorithms">algorithme d&#39;étalonnage de xDrip</a>.</p><h3 id="history" tabindex="-1">Historique <a class="header-anchor" href="#history" aria-label="Permalink to &quot;Historique {#history}&quot;">​</a></h3><p>Lorsque vous utilisez xDrip depuis un certain temps, l&#39;historique vous permet de parcourir les anciennes données.</p><div class="admonition xdripitem"><p class="admonition-title">Historique</p></div><ol><li>parcourir le ou les jours précédents</li><li>parcourir le ou les jours suivants</li><li>définir le nombre de jours affichés à l&#39;écran (de 1 à 14)</li><li>activer ou désactiver les statistiques</li></ol><img src="'+s+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.03.27" target="_blank" rel="noreferrer"><em>Dernière modification le 28/3/2022</em></a></p>',21)])])}const b=r(n,[["render",l]]);export{v as __pageData,b as default};
